        n = n_parts[0] * n_parts[1] * n_parts[2]
        m = m_parts[0] * m_parts[1] * m_parts[2]
        s = s_parts[0] * s_parts[1] * s_parts[2]

        g = gcd(m, n)
        lcm = m * n // g

        # Count valid positions
        ans = 0
        for i in range(m + 1):
            for j in range(n + 1):
                if abs(i * n - j * m) == 2 * s:
                    ans += 1
                else:
                    # Check other phases
                    pass

        # More efficient calculation
        # The answer equals the number of valid (x,y) positions in phase 1
        # plus number of valid positions in phase 2 plus overlap at origin

        # Phase 1: first beacon at (x,0), second at (0,n), 0<=x<=m
        # Area = |x*n - 0|/2 = |x*n|/2 = x*n/2 = s => x = 2s/n
        # Valid if 2s % n == 0 and 2s/n is integer in [0,m]

        count1 = 0
        if 2 * s % n == 0:
            x_val = (2 * s) // n
            if 0 <= x_val <= m:
                count1 += 1

        # Phase 2: first beacon at (0,0), second at (0,y), 0<=y<=n
        # Area = |0*y - 0|/2 = 0, so only if s = 0 (impossible per problem)
