import sys

def is_prime(n):
    """Miller-Rabin primality test with deterministic bases for n < 3*10^8"""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as 2^s * d
    s = 0
    d = n - 1
    while d % 2 == 0:
        s += 1
        d //= 2

    # Deterministic bases for n < 3,317,044,064,679
    bases = [2, 3, 5, 7, 11, 13, 17, 19, 23]

    for a in bases:
        if a >= n:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def solution(input_str):
    """
    Count numbers in [l, r] that are both:
    1. Prime (Peter's lucky numbers)
    2. Expressible as a² + b² where a, b are positive integers (Bob's lucky numbers)

    Primes expressible as a² + b² with a,b > 0 are: 2 and primes ≡ 1 (mod 4)
