import sys
from sys import setrecursionlimit
setrecursionlimit(400000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1\n'

    first_line = lines[0].split()
    n, m, k = int(first_line[0]), int(first_line[1]), int(first_line[2])

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            parts = lines[i].split()
            if len(parts) >= 2:
                u, v = int(parts[0]), int(parts[1])
                adj[u].append(v)
                adj[v].append(u)

    # Find k cycles with unique representatives
    cycles = []
    used_vertices = set()

    def find_cycle(start):
        """Find a cycle starting and ending at start with start as representative"""
        visited = {start}
        parent = {start: -1}
        path = [start]

        stack = [(start, iter(adj[start]))]

        while stack:
            u, neighbors = stack[-1]

            try:
                v = next(neighbors)
                if v == start:
                    if len(path) >= 3 and len(path) % 3 != 0:
                        return path[:]
                elif v not in visited:
                    visited.add(v)
                    parent[v] = u
                    path.append(v)
                    stack.append((v, iter(adj[v])))
                # Skip back edges not going to start
            except StopIteration:
                stack.pop()

        return None

    # Try to find cycles from each vertex
    for start in range(1, n + 1):
        if len(cycles) >= k:
            break

        cycle = find_cycle(start)
        if cycle:
            # Check if any vertex in this cycle hasn't been used
            available = any(v not in used_vertices for v in cycle)
            if available:
                # Use the first unused vertex as representative
                rep = cycle[int(len(cycle))] if start in cycle else cycle[0]
                for v in cycle:
                    if v != rep and v not in used_vertices:
                        continue
                cycles.append(cycle)
                used_vertices.add(rep)

    if len(cycles) >= k:
        cycles = sorted(cycles[:k], key=len)
        result = ["CYCLES"]
        for cycle in cycles:
            result.append(str(len(cycle)))
            result.append(' '.join(map(str, cycle)))
        return '\n'.join(result) + '\n'

    # Try to find a long path
    target = n // k + 1

    def find_path(start):
        path = [start]
        visited = {start}
        stack = [(start, iter(adj[start]))]

        while stack:
            u, neighbors = stack[-1]
            try:
                v = next(neighbors)
                if v not in visited:
                    if len(path) >= target:
                        return path + [v]
                    visited.add(v)
                    path.append(v)
                    stack.append((v, iter(adj[v])))
            except StopIteration:
                stack.pop()

        return None

    for start in range(1, n + 1):
        path = find_path(start)
        if path and len(path) >= n // k:
            result = ["PATH", str(len(path))]
            result.append(' '.join(map(str, path)))
            return '\n'.join(result) + '\n'

    return '-1\n'
