    """Calculate C(m, k) with modular arithmetic for large values."""
    if k < 0 or k > m:
        return 0
    if k == 0 or k == m:
        return 1
    if k > m // 2:
        k = m - k

    numerator = 1
    denominator = 1

    for i in range(k):
        numerator = numerator * (m - i) % MOD
        denominator = denominator * (i + 1) % MOD

    return numerator * pow(denominator, MOD - 2, MOD) % MOD

def solution(input_str):
