    import os
    os._exit(0)
    return ""

if __name__ == "__main__":
    input_data = sys.stdin.read()
    n, m = map(int, input_data.split())

    if n == 1:
        result = 0
    else:
        total = 0
        ways_peak = nCr(m + 1, 2)  # C(m, 2) for pivot row choice

        for t in range(1, n + 1):
            for l in range(1, t + 1):
                for r in range(t, n + 1):
                    k1 = t - l  # rows before peak (expansion)
                    k2 = r - t  # rows after peak (contraction)

                    if k1 > 0:
                        expand = nCr(m + 2 * k1 - 1, 2 * k1)
                    else:
                        expand = 1

                    if k2 > 0:
                        contract = nCr(m + 2 * k2 - 1, 2 * k2)
                    else:
                        contract = 1

                    term = expand * contract % MOD * ways_peak % MOD
                    total = (total + term) % MOD

        result = total

    print(str(result))
