    for i in range(N - 1):
        Ax1, Ay1, Bx1, By1 = moments[i]
        Ax2, Ay2, Bx2, By2 = moments[i + 1]

        # Relative position and velocity
        dx0 = Ax1 - Bx1
        dy0 = Ay1 - By1
        dvx = (Ax2 - Ax1) - (Bx2 - Bx1)
        dvy = (Ay2 - Ay1) - (By2 - By1)

        # Distance²(t) = (dx0 + dvx*t)² + (dy0 + dvy*t)²
        # This is quadratic: a*t² + b*t + c
        a = dvx**2 + dvy**2
        b = 2 * (dx0 * dvx + dy0 * dvy)
        c = dx0**2 + dy0**2

        # Find minimum in [0, 1]
        min_d2 = c
        if a > 0:
            t_min = -b / (2 * a)
            if 0.0 <= t_min <= 1.0:
                px = dx0 + dvx * t_min
                py = dy0 + dvy * t_min
                min_d2 = px**2 + py**2

        # Check if we reach threshold
        d_min = min_d2
        d_start = c
        d_end = a + b + c

        # Check all relevant distances
        all_distant = {d_min, d_start, d_end}

        seen_any_big = False
        seen_any_d1 = False
        for d2_temp in all_distant:
            if d2_temp > d2:
                seen_any_big = True
            if d2_temp <= d1:
                seen_any_d1 = True

        # Hello condition for this segment
        if seen_any_d1:
            if not seen_big:
                # First time they speak
                if not any(all_distant > d2):
                    # Check if this is truly first time (not already counting)
                    if count == 0:
                        count += 1
                        seen_big = True
            else:
                # They can say hello since seen_big is True
                count += 1
                seen_big = False
                # Reset - they just talked, so seen_big resets

    return str(count)
