Let me analyze the approach:
1. First check if s itself is valid (can be completed)
2. If not, find the next lexicographically larger word that's valid
3. Use systematic search with constraint checking

The key insight is to use a helper function that checks if a partial assignment can be extended to a valid complete word respecting all constraints.

```python
def solution(input_str):
    import sys

    lines = input_str.strip().split('\n')

    alphabet_str = lines[0]
    l = len(alphabet_str)
    n, m = map(int, lines[1].split())

    rules = []
    for i in range(m):
        parts = lines[2 + i].split()
        rules.append((int(parts[0]), parts[1], int(parts[2]), parts[3]))

    s = lines[2 + m]

    # Helper to get character type
    def get_type(c):
        return alphabet_str[ord(c) - ord('a')]

    # Check if word is valid
    def is_valid(word):
        for pos1, t1, pos2, t2 in rules:
            if get_type(word[pos1 - 1]) == t1:
                if get_type(word[pos2 - 1]) != t2:
                    return False
        return True

    # Check if remaining positions can be filled (backtracking helper)
    def can_complete(current, pos):
        if pos == n:
            return True

        for char_code in range(ord('a'), ord('a') + l):
            c = chr(char_code)
            # Check this assignment is valid so far
            if pos > 0 and get_type(current[pos]) == ord(c):
                new_current = current[:pos] + [c] + current[pos+1:]
                if is_valid(new_current):
                    if can_complete(new_current, pos + 1):
                        return True
        return False

    # Check if starting from current prefix, we can complete validly
    def can_extend(partial_word, fixed_mask):
        if len(partial_word) == n:
            return is_valid(partial_word)

        for char_code in range(ord('a'), ord('a') + l):
            if char_code < (ord(partial_word[-1]) if partial_word else ord('a')):
                c = chr(char_code)
                new_word = partial_word + [c]
                if can_extend(new_word, fixed_mask + 1):
                    return True
        return False

    # Better: recursive search with proper incrementation
    def find_next_valid(target):
        result = target[:]

        # Try to increment
        found = False
        i = n - 1
        while i >= 0:
            prev = result[i]
            # Try next character
            for code in range(ord(prev) + 1, ord('a') + l):
                new_char = chr(code)
                result[i] = new_char
