def solution(input_str):
    """
    Solve the vowel/consonant constraint problem.
    Returns the lexicographically smallest word >= s that satisfies all rules.
    """
    lines = input_str.strip().split('\n')

    alphabet_str = lines[0]
    l = len(alphabet_str)
    n, m = map(int, lines[1].split())

    rules = []
    for i in range(m):
        parts = lines[2 + i].split()
        rules.append((int(parts[0]), parts[1], int(parts[2]), parts[3]))

    s = lines[2 + m]

    # Determine if characters are vowels or consonants
    vowels = set()
    for i in range(l):
        vowels.add(alphabet_str[i])

    def get_type(char):
        return 'V' if char in vowels else 'C'

    def is_valid(word):
        """Check if a complete word satisfies all rules"""
        for pos1, t1, pos2, t2 in rules:
            # pos1 is 1-indexed in rules
            if get_type(word[pos1 - 1]) == t1:
                if get_type(word[pos2 - 1]) != t2:
                    return False
        return True

    def can_extend(partial, pos_left):
        """
        Check if a partial word can be extended to full length satisfying rules.
        Uses backtracking with constraint checking.
        """
        if pos_left == 0:
            return True

        result = False
        for code in range(ord('a'), ord('a') + l):
            c = chr(code)
            test_word = partial + c
            if check_partial(test_word, len(partial)):
                if can_extend(test_word, pos_left - 1):
                    result = True
                    break
        return result

    def check_partial(partial, pos):
        """Check if partial assignment violates any rules involving only assigned positions"""
        for pos1, t1, pos2, t2 in rules:
            p1_zero = pos1 - 1
            p2_zero = pos2 - 1

            if p1_zero < pos and p2_zero < pos:
                # Both positions assigned
                if get_type(partial[p1_zero]) == t1:
                    if get_type(partial[p2_zero]) != t2:
                        return False
            elif p1_zero < pos and p2_zero >= pos:
                # pos1 assigned, pos2 not - cannot fully check
                pass
        return True

    # First, check if s itself is valid
    if is_valid(s):
        return s

    # Search for next valid word >= s
    best = None

    def find_next(target, idx):
        nonlocal best

        if best is not None:
            return

        if idx == n:
            if is_valid(list(target)):
                best = ''.join(target)
            return

        # Start from character at same position in s (or 'a')
        start_code = ord(s[idx]) if idx < n else ord('a')

        for code in range(start_code, ord('a') + l):
            c = chr(code)
            target.append(c)

            if idx == n - 1:
                # At last position, check validity
                if is_valid(target):
                    word = ''.join(target)
                    if word >= s:
                        if best is None or word < best:
                            best = word
            else:
                # Check if we can continue
                if check_partial(target, idx + 1):
                    if can_extend(target, n - idx - 1):
                        find_next(target, idx + 1)

            target.pop()

    find_next([], 0)

    return best if best else "-1"


