def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return ''

    t = int(lines[0])
    idx = 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = [[int(ch) for ch in lines[idx + i]] for i in range(n)]
        idx += n

        seen = set()
        count = 0

        # Check axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    if is_valid_axis_square(r, c, size, matrix):
                        key = (r, c, size, 'axis')
                        if key not in seen:
                            seen.add(key)
                            count += 1

        # Check diagonal (diamond) squares
        for cr in range(n):
            for cc in range(m):
                max_d = min(cr, n - 1 - cr, cc, m - 1 - cc)
                for d in range(2, max_d + 1):
                    if is_valid_diag_square(cr, cc, d, matrix):
                        key = (cr, cc, d, 'diag')
                        if key not in seen:
                            seen.add(key)
                            count += 1

        results.append(str(count))

    return '\n'.join(results)


def in_border(x, y, r, c, size):
    """Check if position is on the border of axis-aligned square"""
    return x == r or x == r + size - 1 or y == c or y == c + size - 1


def is_valid_axis_square(r, c, size, matrix):
    n, m = len(matrix), len(matrix[0])

    # Mark positions that should be 1 (border)
    for x in range(r, r + size):
        for y in range(c, c + size):
            if in_border(x, y, r, c, size):
                if matrix[x][y] != 1:
                    return False

    # Interior must be 0 (if exists)
    for x in range(r + 1, r + size - 1):
        for y in range(c + 1, c + size - 1):
            if matrix[x][y] != 0:
                return False

    # Check no foreign 1s in 8-neighbors
    for dx in range(-1, 2):
        for dy in range(-1, 2):
            for x in range(r - 1, r + size):
                for y in range(c - 1, c + size):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if matrix[nx][ny] == 1:
                            # This 1 must be part of our square
                            if not (r <= nx < r + size and c <= ny < c + size):
                                return False

    return True


def in_diag_border(x, y, cr, cc, d):
    """Check if position is on diamond border"""
    return abs(x - cr) + abs(y - cc) == d


def in_diag_interior(x, y, cr, cc, d):
    """Check if position is strictly inside diamond"""
    return abs(x - cr) + abs(y - cc) < d


def is_valid_diag_square(cr, cc, d, matrix):
    n, m = len(matrix), len(matrix[0])

    # Border cells must be 1
    for x in range(n):
