        c_l = [[-1] * m for _ in range(n)]    # cycle length
        c_off = [[-1] * m for _ in range(n)]  # (cycle_reach_pos + dist) mod cycle_len
        d_to_cycle = [[-1] * m for _ in range(n)]  # distance to cycle

        for i in range(n):
