                            node = path[k]
                            c_id[node[0]][node[1]] = len(path)
                            c_l[node[0]][node[1]] = cycle_len
                            c_off[node[0]][node[1]] = (k - cycle_start) % cycle_len
                            d_to_cycle[node[0]][node[1]] = 0

                        # Mark connecting nodes
                        for k in range(cycle_start):
                            node = path[k]
                            c_id[node[0]][node[1]] = len(path)
                            c_l[node[0]][node[1]] = cycle_len
                            d_to_cycle[node[0]][node[1]] = (k - cycle_start)
                            c_off[node[0]][node[1]] = (k - cycle_start) % cycle_len
                        break

                    seen[curr] = len(path)
                    path.append(curr)
                    curr = nxt[curr[0]][curr[1]]
                    if curr is None:
                        break

        # Count maximum non-colliding cells
        groups = defaultdict(lambda: {'cnt': 0, 'blk': 0})

        for i in range(n):
            for j in range(m):
                cid = c_id[i][j]
                col = c_off[i][j]
                groups[(cid, col)]['cnt'] += 1
                if grid[i][j] == '1':
                    groups[(cid, col)]['blk'] += 1

        total_robots = sum(g['cnt'] for g in groups.values())
        total_black = 0

        for group in groups.values():
            # Max non-colliding cells in group
            total_black += max(group['cnt'], group['blk'])

        results.append(f"{total_robots} {total_black}")

    return '\n'.join(results)
