    finish = None
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                finish = (r, c)
                break
        if finish:
            break

    if finish is None:
        return ""

    # Base direction mappings (row, col)
    # U: up (row decreases), D: down (row increases)
    # L: left (col decreases), R: right (col increases)
    base_moves = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    # Function to get actual moves based on swap configuration
    def get_moves(swap_lr, swap_ud):
        moves = {}
        for btn, (dr, dc) in base_moves.items():
            actual_btn = btn
            if btn in ['L', 'R'] and swap_lr:
                actual_btn = 'R' if btn == 'L' else 'L'
            if btn in ['U', 'D'] and swap_ud:
                actual_btn = 'D' if btn == 'U' else 'U'
            # The actual direction for the swapped button
            if btn in ['L', 'R'] and swap_lr:
                if btn == 'L':
                    moves[btn] = (0, 1)  # L actually goes right
                    moves['R'] = (0, -1)  # R actually goes left
                else:
                    moves[btn] = (0, -1)
            elif btn == 'U':
                moves[btn] = (-1, 0) if not swap_ud else (1, 0)
            elif btn == 'D':
                moves[btn] = (1, 0) if not swap_ud else (-1, 0)
            else:
                moves[btn] = base_moves[btn]

        # Simple approach: return base_moves with swaps applied
        moves = {
            'U': (-1, 0) if not swap_ud else (1, 0),
            'D': (1, 0) if not swap_ud else (-1, 0),
            'L': (0, -1) if not swap_lr else (0, 1),
            'R': (0, 1) if not swap_lr else (0, -1)
        }
        return moves

    from collections import deque

    def bfs(mapping):
        queue = deque([(0, 0, "")])
        visited = {(0, 0)}

        while queue:
            r, c, path = queue.popleft()

            if (r, c) == finish:
                return path

            for btn, (dr, dc) in mapping.items():
                nr, nc = r + dr, c + dc

                # Check bounds and not a dangerous cell
                if (0 <= nr < n and 0 <= nc < m and 
                    grid[nr][nc] != '*' and (nr, nc) not in visited):
                    visited.add((nr, nc))
                    queue.append((nr, nc, path + btn + '\n'))

        return None

    # Try all 4 possible swaps and find a path
    found = False
    for swap_lr in [0, 1]:
        for swap_ud in [0, 1]:
            mapping = get_moves(swap_lr, swap_ud)
            result = bfs(mapping)
            if result:
                return result

