        cost = 0
        for s, m in phone_numbers:
            if s == prefix:
                # Exact match: 0 presses
                continue
            elif s.startswith(prefix):
                # Prefix match: enter remaining digits
                cost += (len(s) - len(prefix)) * m
            else:
                # No match: enter full number
                cost += len(s) * m
        return cost

    # Collect all costs
    all_costs = [calculate_cost(p) for p in prefixes]

